// Üretilen dosya: tool/ozgun/uret.py. Tarih · Amerika ve Afrika tarihi: yerli uygarlıklar, sömürgecilik, bağımsızlıklar (kolay).
const ozHistory12Kolay = <(String, String, List<String>, String)>[
  ('K\'iche\' Maya halkının yaratılış öyküsünü ve kahraman ikizlerin serüvenlerini anlatan, 16. yüzyılda Latin harfleriyle kaydedilen metin hangisidir?', 'Popol Vuh', ['Chilam Balam', 'Kalevala', 'Rig Veda'], 'Popol Vuh, Guatemala yaylalarındaki K\'iche\' halkının mitolojisini aktarır; insanların mısırdan yaratılması anlatısıyla tanınır.'),
  ('Maya sayı gösteriminde bir nokta 1, bir yatay çubuk 5 değerindedir. Tek basamaklı bir sayıda iki çubuk ile üç nokta yan yana konmuşsa bu sayı kaçtır?', '13', ['10', '15', '23'], 'İki çubuk 2x5=10, üç nokta 3 eder; toplam 13 olur.'),
  ('Klasik dönemde Tikal ile uzun süre güç mücadelesi veren, bugünkü Meksika\'nın Campeche eyaletindeki Maya kenti hangisidir?', 'Calakmul', ['Palenque', 'Uxmal', 'Yaxchilán'], 'Tikal ile Calakmul, Klasik Maya dünyasının iki büyük gücüydü ve diğer şehir devletlerini kendi yanlarına çekmeye çalışırdı.'),
  ('Meksika\'nın Chiapas eyaletindeki Palenque kentinde Yazıtlar Tapınağı\'nın altındaki mezar odasında bulunan hükümdar kimdir?', 'K\'inich Janaab\' Pakal', ['II. Moctezuma Xocoyotzin', 'Atahualpa', 'Pachacuti'], 'Pakal 7. yüzyılda yaklaşık 68 yıl hüküm sürdü; mezarı 1952\'de keşfedildi ve Mezoamerika piramitlerinin mezar olarak da kullanıldığını gösterdi.'),
  ('Yucatán\'da 1562\'de Maní\'deki olayda yüzlerce Maya kodeksini yaktıran Fransisken piskopos kimdir?', 'Diego de Landa', ['Bartolomé de las Casas', 'Francisco Pizarro', 'Pedro de Alvarado'], 'Landa, putperestlik saydığı yazılı kayıtları yok ettirdi; bugün yalnızca dört kadar Maya kodeksi günümüze ulaşmıştır.'),
  ('Dresden Kodeksi\'nde yer alan ve Maya astronomisinin ürünü sayılan tablolar hangi gök cismine ilişkin hesaplar içerir?', 'Venüs', ['Satürn', 'Halley Kuyruklu Yıldızı', 'Neptün'], 'Kodeksteki tablolar Venüs\'ün gökyüzündeki döngüsünü izler; Mayalar bu gezegeni savaş ve törenlerle ilişkilendirirdi.'),
  ('Mezoamerika uygarlıklarında kullanılan bir top oyununun oynandığı toplar hangi hammaddeden yapılırdı?', 'Kauçuk', ['Deri ve hurma lifi', 'Kil', 'Odun'], 'Mezoamerikalılar kauçuk ağacının sütünü işleyerek zıplayan toplar yapmıştır; bu malzeme Avrupalılar için bir yeniliktir.'),
  ('Metal alet kullanımının sınırlı olduğu Mezoamerika\'da kesici aletlerin ve mızrak uçlarının yapımında en çok hangi malzeme kullanılmıştır?', 'Obsidyen', ['Çelik', 'Pirinç', 'Dökme demir ve bronz'], 'Volkanik cam olan obsidyen çok keskin kenar verdiği için hem alet hem silah yapımında yaygındı ve ticarete konu olurdu.'),
  ('Oaxaca vadisinde Monte Albán kentini kuran ve Mezoamerika\'nın erken yazı örneklerini bırakan halk hangisidir?', 'Zapotekler', ['Toltekler', 'Tlaxcalalılar', 'Taínolar'], 'Monte Albán, bir dağ tepesinin düzleştirilmesiyle kurulmuş Zapotek başkentidir.'),
  ('Aztekler kendilerini hangi önceki uygarlığın kültürel mirasçısı olarak görür, ona \'ustalık\' atfederdi?', 'Toltekler', ['Olmekler', 'Mochelar', 'Paracaslar'], 'Aztekler Tula merkezli Toltek hanedanını soylu bir atalar çağı saydı ve hükümdarlarını bu soyla ilişkilendirmeye çalıştı.'),
  ('Olmek kültürünün ilk büyük merkezlerinden San Lorenzo ve La Venta hangi kıyı bölgesinde yer alır?', 'Meksika Körfezi kıyısında', ['Pasifik kıyısında Peru\'da', 'Karayipler\'de Küba\'da', 'Yucatán\'ın doğu kıyısında'], 'Olmekler yaklaşık MÖ 1200\'den itibaren Meksika Körfezi\'nin sıcak ve nemli ovalarında gelişti.'),
  ('Copán Maya kentinin kalıntıları bugün hangi ülkenin topraklarında yer alır?', 'Honduras', ['Peru', 'Bolivya', 'Kolombiya'], 'Copán, Maya dünyasının güneydoğu ucunda olup yazıtlarla kaplı merdivenleriyle tanınır.'),
  ('Maya ve Aztek kodekslerinin yapımında kullanılan, incir ağacı kabuğundan elde edilen yazı malzemesi hangisidir?', 'Amate kâğıdı', ['Papirüs', 'Parşömen', 'Pirinç kâğıdı'], 'Mezoamerikalılar ağaç kabuğunu dövüp sıvayarak kâğıt benzeri levhalar yapar, bunları katlayarak kitaplar oluştururdu.'),
  ('Teotihuacan\'ın en büyük yapısı olan ve kentin ana caddesinin doğusunda yer alan anıt hangisidir?', 'Güneş Piramidi', ['Ay Piramidi', 'Büyük Tapınak', 'El Castillo'], 'Güneş Piramidi, Mezoamerika\'nın en büyük yapılarından biridir; adı sonradan Azteklerce verilmiştir.'),
  ('Texcoco Gölü\'ndeki ada kentin kuruluşuna ilişkin efsane, kaktüs üzerinde yılan yutan bir kartalı anlatır. Bu simge bugün hangi ülkenin bayrağında yer alır?', 'Meksika', ['Peru', 'Guatemala', 'Şili'], 'Aztek (Meksika) halkının göç öyküsüne göre tanrı Huitzilopochtli\'nin gösterdiği bu işaret yerleşim yerini belirlemiştir; simge Meksika bayrağının ortasındadır.'),
  ('Aztek hükümdarlarının taşıdığı \'Tlatoani\' unvanı sözcük anlamı olarak neyi ifade eder?', 'Konuşan, buyuran kişi', ['Güneşin oğlu', 'Dağların efendisi', 'Güneşin ve ayın hükümdarı'], 'Nahuatl dilinde tlatoani, \'konuşan\' anlamına gelir; Aztek hükümdarı tanrılar ve halk adına söz söyleyen kişi sayılırdı.'),
  ('Aztek imparatorluğunun haraç listelerini resimli biçimde gösteren ve İspanyol yönetimince hazırlatılan kaynak hangisidir?', 'Mendoza Kodeksi', ['Dresden Kodeksi', 'Rosetta Taşı', 'Chilam Balam kitapları'], 'Mendoza Kodeksi, 16. yüzyılda Yeni İspanya\'nın ilk genel valisi adına hazırlandı; Aztek tarihini ve haraçları bildiren önemli bir kaynaktır.'),
  ('Cortés\'in Tenochtitlan\'a yürüyüşü sırasında Aztek karşıtı ittifak kurduğu, imparatorluğa direnen halk hangisidir?', 'Tlaxcalalılar', ['Zapotekler', 'Mayalar', 'Yucatán Maya şehirleri'], 'Tlaxcala, Aztek egemenliğine hiç boyun eğmemişti; savaşta yenildikten sonra Cortés\'in yanında binlerce savaşçı gönderdi.'),
  ('Cortés\'e tercümanlık yapan ve Nahuatl ile Maya dillerini bilen kadın hangisidir?', 'Malintzin (La Malinche)', ['Pocahontas', 'Sacagawea', 'Kraliçe Isabel (Kastilya)'], 'Malinche, Cortés\'in iletişimini sağladı; Meksika\'da hem fetihle iş birliği yapan hem de melez halkın simgesi olarak tartışmalı biçimde anılır.'),
  ('Aztek hükümdarı II. Moctezuma\'nın, Cortés\'in Tenochtitlan\'a girişinde onu karşılaması hangi yılda olmuştur?', '1519', ['1492', '1532', '1545'], 'Cortés 1519\'da Tenochtitlan\'a ulaştı ve Moctezuma onu şehre aldı; kısa süre sonra İspanyollar hükümdarı tutsak etti.'),
  ('Haziran 1520\'de İspanyolların Tenochtitlan\'dan ağır kayıplarla kaçtığı olay, tarihte hangi adla anılır?', 'Üzüntü Gecesi', ['Kanlı Pazar', 'Uzun Yürüyüş', 'Tenochtitlan\'dan Kaçış Gecesi'], 'İspanyollar kentten kaçarken kanallarda ve set yollarında çok sayıda adam ve ganimet yitirdi; olay \'Noche Triste\' olarak bilinir.'),
  ('1521\'de Tenochtitlan\'ın düşüşü sırasında kentin son Aztek hükümdarı kimdir?', 'Cuauhtémoc', ['Cuitláhuac', 'Atahualpa', 'Pachacuti Inca Yupanqui'], 'Cuauhtémoc, İspanyol kuşatmasına karşı kenti savundu; 13 Ağustos 1521\'de esir alındı.'),
  ('Azteklerin başkenti Tenochtitlan\'ın merkezinde yer alan ve yağmur tanrısı Tlaloc ile savaş tanrısı Huitzilopochtli\'ye adanan ana tapınağın adı nedir?', 'Templo Mayor', ['Teotihuacan Güneş Tapınağı', 'Sacsayhuamán', 'Koricancha'], 'Templo Mayor, kentin kutsal merkeziydi; kalıntıları bugün Mexico City\'nin merkezinde bulunmaktadır.'),
  ('Aztek soylu çocuklarının eğitim gördüğü okulun adı nedir?', 'Calmecac', ['Telpochcalli', 'Quipucamayoc', 'Ayllu'], 'Calmecac soylu ve rahip adayı çocukların; telpochcalli ise halk çocuklarının askerî ağırlıklı eğitim aldığı okullardı.'),
  ('Bugün Türkçede kullanılan \'çikolata\', \'domates\' ve \'avokado\' gibi sözcüklerin dilimize Avrupa dilleri aracılığıyla geçen kökeni hangi dile dayanır?', 'Nahuatl', ['Quechua', 'Yucatec Mayacası', 'Maya'], 'Bu sözcükler Aztek halkının Nahuatl diline ait xocolatl, tomatl ve ahuacatl sözcüklerinden gelir.'),
  ('Azteklerin Tenochtitlan\'ın göl içindeki konumunu karayla bağlamak için kullandığı yapılar hangileridir?', 'Set yollar ve su yolları üzerindeki köprüler', ['Teleferikler', 'Taş tüneller', 'Demiryolları'], 'Kent, göl kıyısıyla geniş set yollarla bağlanıyordu; köprülerin kaldırılması kenti savunmada avantajlı kılıyordu.'),
  ('Aztek toplumunda uzak ülkelerle ticaret yapan ve aynı zamanda casusluk görevi üstlenebilen tüccar sınıfa ne ad verilir?', 'Pochteca', ['Tlatoani', 'Quipucamayoc', 'Cacique'], 'Pochteca, imparatorluğun sınırlarını aşan ticareti yürütür; aldıkları bilgiler seferlere zemin hazırlayabilirdi.'),
  ('1520 baharında Pedro de Alvarado\'nun Aztek soylularını katlettiği olay, hangi Aztek dinî bayramı sırasında yaşanmıştır?', 'Toxcatl bayramı', ['Inti Raymi bayramı', 'Yeni Ateş Töreni', 'Kukulkan şenliği'], 'Cortés kentte yokken Alvarado, bayram sırasındaki soylu dansçıları kılıçtan geçirdi ve bu olay Aztek ayaklanmasının fitilini ateşledi.'),
  ('İnka devleti yazıyı kullanmadan geniş bir imparatorluğu yönetmiştir. Bu yönetimde sayısal kayıtlar hangi araçla tutulmuştur?', 'Renkli ipler üzerindeki düğümlerle', ['Kil tabletler üzerine çivi yazısıyla', 'Taş levhalara oyulan hiyerogliflerle', 'Ağaç kabuğu kâğıtlara çizilen resimlerle'], 'Quipu, düğümlerin türüne ve konumuna göre nüfus, hasat ve haraç bilgilerini saklayan bir kayıt sistemidir; yetkililer bunu okuyabilirdi.'),
  ('İnka İmparatorluğu\'nda halkın devlete vergi olarak belirli süre için yol, köprü ve maden işlerinde çalışması sistemine ne ad verilir?', 'Mit\'a', ['Encomienda', 'Haraç', 'Timar'], 'Mit\'a, nakit vergi yerine emek yükümlülüğüydü; İspanyollar bu sistemi Potosí madenlerinde değiştirilmiş biçimde sürdürdü.'),
  ('İnkaların \'dört bölgenin ülkesi\' anlamına gelen kendi imparatorluk adı nedir?', 'Tawantinsuyu', ['Tenochtitlan', 'Tiwanaku', 'Chavín de Huántar'], 'Tawantinsuyu, Cuzco\'dan dört yöne uzanan idari bölgeleri anlatır; Quechua dilinde \'dört parça bir arada\' demektir.'),
  ('İnka yol ağı (Qhapaq Ñan) boyunca belirli aralıklarla konaklama ve depo yapıları ile hızlı haber taşıyan koşucu görevliler bulunurdu. Bu görevlilere ne ad verilirdi?', 'Chasqui', ['Quipucamayoc', 'Curaca', 'Yanacona'], 'Chasqui\'ler, bir etaptan diğerine koşarak haberleri ve küçük yükleri çok kısa sürede ulaştırırdı; böylece merkezî denetim güçleniyordu.'),
  ('And Dağları\'nın dik yamaçlarında tarım yapan İnkalar, toprağı nasıl işlemiştir?', 'Basamaklı teraslar (andenes) oluşturarak', ['Yamaçları düz ovalara dönüştürerek', 'Tarlaları göl üzerinde yapay adalara kurarak', 'Yalnızca yağmura dayalı sık ormanları açarak'], 'Taşla desteklenmiş teraslar toprak kaymasını önler, sulamayı kolaylaştırır ve farklı yükseklikte farklı ürün yetiştirmeye olanak verirdi.'),
  ('Yüksek And bölgesinde patatesin dondurularak kurutulmasıyla elde edilen ve uzun süre saklanabilen besin maddesinin adı nedir?', 'Chuño', ['Chicha', 'Tamale', 'Pemmican'], 'Chuño, geceleri donan, gündüzleri çözülen patatesin ezilip kurutulmasıyla yapılır; ordu ve depolar için stratejik bir yiyecekti.'),
  ('İnka İmparatorluğu\'nu yaklaşık 1438\'den itibaren hızla genişleterek Cuzco\'yu bir imparatorluk merkezine dönüştüren hükümdar kimdir?', 'Pachacuti', ['Manco Capac', 'Huáscar', 'Túpac Amaru'], 'Pachacuti döneminde İnkalar küçük bir kent devletinden büyük bir imparatorluğa dönüştü; Machu Picchu da onun dönemine bağlanır.'),
  ('Pizarro\'nun 1535\'te kurduğu ve İspanyol Güney Amerika yönetiminin merkezi olan kent hangisidir?', 'Lima', ['Cuzco', 'Santiago', 'Buenos Aires'], 'Pizarro, kıyıya yakın olması nedeniyle Lima\'yı seçti; kent Peru Genel Valiliği\'nin başkenti oldu.'),
  ('İspanyol egemenliğine karşı Vilcabamba\'da direniş sürdüren Neo-İnka devletinin son hükümdarı Túpac Amaru\'nun idamı hangi yüzyılda gerçekleşmiştir?', '16. yüzyılda', ['15. yüzyılda', '17. yüzyılda', '18. yüzyılın başlarında'], 'Vilcabamba 1572\'de düştü ve I. Túpac Amaru Cuzco\'da idam edildi; yerli İnka siyasi iktidarı böylece sona erdi.'),
  ('İnka başkenti Cuzco\'da güneş tanrısına adanmış, altın kaplamalarıyla ünlü ve sonradan İspanyollarca kilise temeli yapılan tapınak hangisidir?', 'Koricancha', ['Templo Mayor', 'Chavín de Huántar', 'Sacsayhuamán'], 'Koricancha (Altın Avlu), İnka dininin en kutsal yapısıydı; Santo Domingo Kilisesi bu taş temellerin üzerine inşa edildi.'),
  ('Güney Amerika\'da Peru kıyısında bulunan ve Amerika kıtasının en eski kentsel merkezlerinden biri sayılan Caral hangi dönemle ilişkilidir?', 'Yaklaşık MÖ 3. binyıl', ['MÖ 1. yüzyıl', 'MS 8. yüzyıl', 'Yaklaşık MS 15. yüzyıl sonu'], 'Caral (Norte Chico), piramit biçimli yapıları ve kıyı balıkçılığı ile iç tarım arasındaki iş bölümüyle bilinir; İnkalardan çok daha eskidir.'),
  ('Güney Amerika\'da Titicaca Gölü çevresinde İnkalardan önce gelişen ve yarı yer altı tapınağı ile Güneş Kapısı\'yla bilinen merkez hangisidir?', 'Tiwanaku', ['Teotihuacan', 'Tikal', 'Chichén Itzá'], 'Tiwanaku, İnkaların atası saydığı kültürlerden biridir; yüksek rakımda tarım tekniklerini geliştirmiştir.'),
  ('Evcil hayvan olarak Güney Amerika\'da yük taşıyıcılığı yapan ve yünü dokumada kullanılan hayvan hangisidir?', 'Lama ve alpaka', ['At', 'Deve ve manda sürüleri', 'Öküz'], 'And bölgesinde lama yük taşırken alpaka ve vikunya yünü dokumacılık için önemliydi; tekerlek kullanılmadığı için yükler lamalarla taşınırdı.'),
  ('Bugünkü Saint Louis yakınlarında Mississippi Vadisi\'nde yükselen ve Monks Mound adlı büyük toprak höyüğüyle tanınan Kızılderili kenti hangisidir?', 'Cahokia', ['Chaco Canyon', 'Mesa Verde', 'Tenochtitlan'], 'Cahokia, 11-12. yüzyıllarda binlerce kişinin yaşadığı, höyüklerle çevrili bir merkezdi; Kolomb öncesi Kuzey Amerika\'nın en büyük kentiydi.'),
  ('Pasifik kıyısının kuzeybatısındaki halkların zenginliği ve sosyal mevkiini göstermek için düzenlediği hediye dağıtma şölenine ne ad verilir?', 'Potlaç', ['Sun Dance', 'Wampum', 'Powwow'], 'Potlaç şölenlerinde ev sahibi servetini dağıtır, böylece toplumsal itibar kazanırdı; somon bolluğu bu zenginliğin dayanağıydı.'),
  ('1621\'de Wampanoag halkının önderi Massasoit ile Plymouth kolonistleri arasında yapılan hasat şenliği hangi geleneğin kökeni sayılır?', 'Şükran Günü', ['Bağımsızlık Günü', 'Cadılar Bayramı', 'Noel Pazarı'], 'Kolonistler, Squanto gibi yerlilerin tarım öğretisi sayesinde ilk hasatı yaptı; bu şölen Amerikan Şükran Günü geleneğinin hikâyesine dönüştü.'),
  ('1675-1676\'da Yeni İngiltere\'de Wampanoag lideri Metacom\'un (Kral Philip) önderliğinde yerlilerle kolonistler arasında yaşanan çatışma tarihte neyle anılır?', 'King Philip Savaşı', ['Pontiac İsyanı', 'Yedi Yıl Savaşları', 'Pequot ve Narragansett Seferi'], 'Savaş, kolonistlerin toprak genişlemesinin yarattığı gerilimden doğdu ve Yeni İngiltere\'de yerli direnişini büyük ölçüde kırdı.'),
  ('1838-1839\'da Cherokee halkının zorla batıya yürütüldüğü ve çok sayıda ölümün yaşandığı olaya ne ad verilir?', 'Gözyaşı Yolu', ['Uzun Yürüyüş', 'Kızıl Yol', 'Georgia Vadisi Sürgün Yürüyüşü'], 'Cherokee halkı, Georgia\'daki topraklarından askerî gözetim altında yürütüldü; hastalık, soğuk ve yoksunluk yüzünden binlerce kişi öldü.'),
  ('29 Aralık 1890\'da Güney Dakota\'da Lakota halkından yüzlerce kişinin öldürüldüğü olay, Kızılderili Savaşları\'nın hangi evresini simgeler?', 'Silahlı direnişin sona erişini', ['Barış antlaşmalarının başlangıcını', 'Federal hükümetin geri çekilişini', 'Bizon sürülerinin yeniden artışını'], 'Wounded Knee Katliamı, büyük çaplı yerli direnişin son aşaması sayılır ve ardından yerlilerin rezervlerde yaşaması kalıcı hâle geldi.'),
  ('Kuzey Amerika\'nın kutup bölgesinde buzdan ya da karla yapılmış barınaklar (iglu) kullanan ve foklar ile balinalarla geçinen halk hangisidir?', 'İnuitler', ['Navajolar', 'Mayalar', 'Cherokeeler'], 'İnuit toplulukları Kanada\'nın kuzeyi ve Grönland\'da kayık ve av araçlarıyla soğuk iklime uyum sağlamıştır.'),
  ('İspanyol Amerika\'sında bir fatihe belirli sayıda yerli halkın emeğinden yararlanma hakkı verilip karşılığında onları korumak ve Hristiyanlaştırmakla yükümlü tutan sisteme ne ad verilir?', 'Encomienda', ['Hacienda', 'Quinto Real ve gümüş vergisi', 'Mit\'a'], 'Encomienda, uygulamada yerlilerin zorla çalıştırılmasına dönüştü; Hispaniola\'dan başlayarak kıtanın geneline yayıldı.'),
  ('İspanyol sömürge toplumunda beyaz babadan ve yerli anneden doğan çocuklara verilen ad aşağıdakilerden hangisidir?', 'Mestizo', ['Mulato', 'Zambo', 'Peninsular'], 'Mestizo, İspanyol ve yerli soyunu taşıyan kişiler için kullanılır; mulato, İspanyol-Afrikalı karışımıdır.'),
  ('Sömürge Latin Amerika\'sında büyük arazilerin sahipleri tarafından yerli ve melez işçilerle işletilen tarım ve hayvancılık çiftliklerine ne ad verilirdi?', 'Hacienda', ['Plantasyon', 'Çiftlik kanunu', 'Pueblo'], 'Hacienda\'lar, borçlu köylülerin toprağa bağlanmasına ve toprak mülkiyetinin birkaç ailede toplanmasına yol açtı.'),
  ('Aşağıdakilerden hangisi Avrupalılarla birlikte Amerika kıtasına ulaşan ve yerlilerin yaşamını değiştiren varlıklardan biridir?', 'At', ['Kakao', 'Mısır', 'Domates'], 'Amerika\'da at kıtadaki evcil hayvan çeşitliliğine Avrupalılarla girdi; Mısır, kakao ve domates ise Amerika kökenlidir.'),
  ('Manila Galyonu olarak bilinen ticaret hattı hangi iki limanı birbirine bağlıyordu?', 'Acapulco ile Manila\'yı', ['Lizbon ile Goa\'yı', 'Sevilla ile Veracruz limanını', 'Cartagena ile Lima\'yı'], 'İspanya, Meksika\'dan Asya\'ya gümüş taşıyıp Çin ipeği ve porselenini getirmek için bu yolu 16. yüzyıldan 19. yüzyıla dek kullandı.'),
  ('18. yüzyılda III. Carlos döneminde İspanyol sömürge yönetimini sıkılaştıran ve gelirleri artırmayı hedefleyen düzenlemeler hangi adla anılır?', 'Bourbon Reformları', ['Yeni Yasalar', 'Tordesillas Düzenlemesi', 'Cadiz Anayasası'], 'Bourbon Hanedanı, sömürgelerde intendant sistemi kurup vergileri artırdı ve yönetimi İspanya doğumlu görevlilere devretti; bu criolloları öfkelendirdi.'),
  ('Amerika kıtasında ilk matbaanın 1539\'da kurulduğu kent hangisidir?', 'Mexico City', ['Boston', 'Lima', 'Santo Domingo'], 'Yeni İspanya\'da matbaa, Katolik dinî metinleri yerli dillerde basmak için kuruldu; kent böylece kıtadaki kültür merkezlerinden biri oldu.'),
  ('Brezilya adının kökeni olarak gösterilen, kırmızı boya veren ağaç hangisidir?', 'Pau-brasil', ['Kakao ağacı', 'Kauçuk ağacı', 'Kahve ve kakao karışımı bitkiler'], 'Portekizlilerin kıyıda ilk işlettiği ürün bu boya ağacıydı; ad zamanla ülkenin tamamına verildi.'),
  ('Brezilya\'nın kuzeydoğu kıyısındaki şeker kamışı plantasyonları hangi işgücüne dayanıyordu?', 'Atlantik köle ticaretiyle getirilen Afrikalı köleler', ['Avrupalı serbest işçiler', 'Çinli ücretli işçiler', 'Yerli ücretli işçiler'], 'Şeker ekonomisinin işgücü talebi büyüktü; yerlilerin azalması ve çalıştırılmalarına karşı çıkılması Afrikalı esirlerin getirilmesini hızlandırdı.'),
  ('Brezilya\'da 17. yüzyılda Zumbi önderliğinde kaçak kölelerin kurduğu büyük topluluğun adı nedir?', 'Quilombo dos Palmares', ['Yeni Amsterdam', 'Port Royal', 'Vilcabamba Neo-İnka Devleti'], 'Palmares, kuzeydoğuda yüzlerce kilometrekarelik alana yayılmış kaçak köle yerleşimiydi; 1694\'te düştü, Zumbi ise sonradan direniş simgesi oldu.'),
  ('17. yüzyılda Brezilya\'nın iç bölgelerine girerek yerli esirler yakalayan ve sonradan altın arayan gruplara ne ad verilirdi?', 'Bandeirantes', ['Criollolar', 'Conquistadorlar', 'Caciqueler'], 'Bandeirantes, São Paulo\'dan çıkan seferlerle Tordesillas sınırını batıya doğru aşıp Brezilya sınırlarının genişlemesine yol açtı.'),
  ('1808\'de Napolyon\'un Portekiz\'i işgali üzerine Portekiz Kraliyet ailesi nereye taşınmıştır?', 'Rio de Janeiro\'ya', ['Madrid\'e', 'Goa\'ya', 'Luanda ve Angola\'ya'], 'Hükümdarın Rio\'ya taşınması Brezilya\'yı fiilen imparatorluğun merkezi yaptı; limanlar dünya ticaretine açıldı.'),
  ('Atlantik köle ticaretinde Afrikalı esirleri Amerika\'ya taşıyan zorlu deniz yolculuğuna ne ad verilir?', 'Orta Geçit', ['Altın Yol', 'Kuzey Geçidi', 'Büyük Atlantik Geri Dönüş Yolu'], 'Üçgen ticaretin ikinci ayağını oluşturan bu yolculukta esirler dar ve sağlıksız koşullarda taşındı; birçoğu yolda öldü.'),
  ('Atlantik köle ticaretinde Afrikalı esirlerin en büyük bölümü hangi bölgeye taşınmıştır?', 'Brezilya\'ya', ['Kuzey Amerika\'ya', 'Küba\'ya', 'Avrupa\'ya'], 'Tahminlere göre Atlantik\'i geçen yaklaşık 12 milyon esirin yarıya yakını Portekiz yönetimindeki Brezilya\'ya ve Karayipler\'deki şeker adalarına gitti, Brezilya tek başına en büyük alıcıydı.'),
  ('Avrupa, Afrika ve Amerika arasındaki üçgen ticarette Afrika\'ya Avrupa\'dan götürülen ürünler arasında en çok hangisi yer alıyordu?', 'Tüfek, barut, kumaş ve alkol', ['Altın ve gümüş', 'Kahve, şeker ve pamuk balyaları', 'Buğday ve pirinç'], 'Avrupalılar ateşli silah ve mamul mallar verip esir alıyor, esirleri Amerika\'da şeker ve pamuk gibi ürünlerle değiştiriyordu.'),
  ('Serbest bırakılan Afrikalı Amerikalıların yerleştirilmesi için 1820\'lerde ABD\'de kurulan \'Amerikan Sömürgeleştirme Derneği\' sonucunda Batı Afrika\'da hangi ülke ortaya çıktı?', 'Liberya', ['Sierra Leone', 'Gana', 'Nijerya'], 'Dernek, serbest siyahları Afrika\'ya göndermeyi amaçladı; Monrovia merkezli koloni 1847\'de bağımsız Liberya Cumhuriyeti\'ne dönüştü.'),
  ('1607\'de Virginia\'da kurulan Jamestown\'un hayatta kalmasını sağlayan ve kolonide kâr getiren ürün hangisidir?', 'Tütün', ['Pamuk', 'Şeker', 'Pirinç'], 'John Rolfe\'un 1610\'ların başında yaygınlaştırdığı tütün Avrupa\'da büyük talep gördü ve Virginia kolonisini ekonomik olarak ayakta tuttu.'),
  ('Virginia\'da 1619\'da toplanan ve İngiliz Amerika\'sında ilk seçilmiş yasama organı sayılan meclisin adı nedir?', 'House of Burgesses', ['Continental Congress', 'Mayflower Meclisi', 'General Court'], 'Meclis, kolonistlerin temsilcilerini bir araya getirdi ve yerel yönetim geleneğinin temelini attı.'),
  ('1620\'de Mayflower gemisinde Plymouth\'a ulaşan Pilgrim\'lerin yolculuk sırasında imzaladığı ve kendi kendilerini yönetme esaslarını belirleyen belge hangisidir?', 'Mayflower Anlaşması', ['Büyük Ferman', 'Haklar Bildirgesi', 'Rhode Island Statüsü'], 'Anlaşma, Pilgrim\'lerin çoğunluk kararlarına uyacaklarını belirtir; Amerikan öz yönetim geleneğinin erken örneklerinden sayılır.'),
  ('William Penn\'in 1681\'de kurduğu Pennsylvania kolonisi hangi inanç topluluğuna sığınak olmuştur?', 'Quakerlar', ['Cizvitler', 'Mormonlar', 'Anglikanlar'], 'Penn, Quaker inancını taşıyan bir toplulukla Philadelphia\'yı (\'kardeşlik kenti\') kurdu; koloni dinî hoşgörüyle birçok göçmeni çekti.'),
  ('1692\'de Massachusetts\'in Salem kasabasında yaşanan olay hangisidir?', 'Cadılık suçlamasıyla yapılan yargılamalar', ['Büyük yangın', 'Kızılderili saldırısı', 'Köle isyanı'], 'Salem\'de yaygın halk korkusu ve dinî gerilim sonucu onlarca kişi cadılıkla suçlandı; bazıları idam edildi.'),
  ('İngiltere\'nin kolonilerinin yalnızca İngiliz gemileriyle ve belirli ürünleri ana ülkeye satmasını zorunlu kılan Seyrüsefer Yasaları\'nın dayandığı iktisadi anlayış nedir?', 'Merkantilizm', ['Fizyokrat tarım okulu', 'Liberalizm', 'Sosyalizm'], 'Merkantilizm, sömürgeleri ham madde kaynağı ve pazar sayarak ana ülkenin altın ve ticaret fazlasını artırmayı amaçlar.'),
  ('1608\'de Samuel de Champlain\'in Quebec\'i kurmasıyla başlayan Fransız Kuzey Amerika varlığının temel ekonomik faaliyeti nedir?', 'Kürk ticareti', ['Tütün çiftçiliği', 'Pirinç plantasyonu', 'Altın madenciliği'], 'Fransızlar yerli halklarla kürk takasına dayalı ticaret yaptı; yerleşimci sayısı İngiliz kolonilerinden çok azdı.'),
  ('1732\'de kurulan ve on üç koloninin sonuncusu olan koloni hangisidir?', 'Georgia', ['Virginia', 'New Jersey', 'Maryland'], 'Georgia, İngiliz borçlular ve İspanyol Florida\'ya karşı tampon bölge olarak kuruldu; adını Kral II. George\'dan aldı.'),
  ('Boston\'da 1770\'te İngiliz askerlerinin kalabalığa ateş açmasıyla yaşanan olay, kolonistlerin propagandasında hangi adla kullanılmıştır?', 'Boston Katliamı', ['Lexington Çatışması', 'Bunker Hill Günü', 'Concord Baskını'], 'Beş kişinin öldüğü olay, İngiliz birliklerinin kentte bulunmasına duyulan öfkeyi artırdı ve bağımsızlık yanlısı yazarlarca geniş biçimde anlatıldı.'),
  ('1774\'te Boston limanını kapatan ve Massachusetts\'in özyönetimini kısıtlayan yasalar kolonistlerce hangi adla anılmıştır?', 'Tahammül Edilmez Yasalar', ['Damga ve Townshend Yasaları', 'Seyrüsefer Yasaları', 'Quebec Yasaları'], 'Boston Çay Partisi\'ne verilen karşılıklar kolonilerde ortak tepkiye yol açtı; Philadelphia\'da Birinci Kıta Kongresi toplandı.'),
  ('Bağımsızlık Bildirgesi\'nin \'yaşam, özgürlük ve mutluluğun peşinde koşma\' hakkı vurgusu hangi düşünürün doğal haklar anlayışından etkilenmiştir?', 'John Locke', ['Thomas Hobbes', 'Niccolò Machiavelli', 'Jean Bodin'], 'Locke\'a göre hükümet yönetilenlerin rızasına dayanır ve doğal hakları korumazsa halk onu değiştirebilir; bu fikir Bildirge\'nin temelidir.'),
  ('Kıta Ordusu\'nun 1777-1778 kışını geçirdiği ve Washington\'ın zorlu koşullarda disiplini sağladığı yer neresidir?', 'Valley Forge', ['Fort Ticonderoga', 'Yorktown', 'Plymouth'], 'Soğuk, açlık ve hastalığa rağmen kamp orduyu sertleştirdi; Prusyalı subay von Steuben eğitimi düzenledi.'),
  ('Devrim sırasında İngiliz Krallığı\'na bağlı kalan ve savaştan sonra çoğu Kanada\'ya göç eden Amerikalılara ne ad verilir?', 'Loyalistler', ['Yurtsever milis güçleri', 'Federalistler', 'Quakerlar'], 'Loyalistler, nüfusun hatırı sayılır bir kesimini oluşturuyordu; birçoğu mallarına el konulunca Kanada ve İngiltere\'ye gitti.'),
  ('Anayasanın onaylanması için Hamilton, Madison ve Jay\'in yazdığı 85 denemeden oluşan eser hangisidir?', 'Federalist Yazıları', ['Anti-Federalist Yazıları', 'Sağduyu', 'Krize Dair'], 'Yazarlar, güçlü bir federal hükümetin özgürlükleri tehdit etmeyeceğini, aksine güçler ayrılığı ve denetim sistemiyle koruyacağını savundu.'),
  ('1836\'da Texas\'ın Meksika\'dan bağımsızlığını kazandığı San Jacinto Savaşı\'nda Meksika ordusunu yenen komutan kimdir?', 'Sam Houston', ['Davy Crockett', 'Andrew Jackson', 'Zachary Taylor'], 'Houston komutasındaki Texaslılar, Alamo\'daki yenilgiden sonra Santa Anna\'yı esir alarak Texas Cumhuriyeti\'nin bağımsızlığını güvence altına aldı.'),
  ('1846\'da ABD ile Büyük Britanya arasında Oregon sorununu çözen anlaşma sınırı nereye çekmiştir?', '49. paralele', ['54. paralele', '36. paralele', 'Mississippi Nehri\'ne'], 'Anlaşma bölgeyi 49. paralelden ikiye böldü; güneyi ABD\'ye, kuzeyi İngiliz Kuzey Amerikası\'na kaldı.'),
  ('1848\'de Kaliforniya\'da altın bulunmasının ardından 1849\'da büyük göç dalgasına katılanlara verilen ad nedir?', 'Forty-niners', ['Pilgrim\'ler', 'Minutemen gönüllü milis birlikleri', 'Loyalistler'], 'Altın hummasıyla yüz binlerce kişi Kaliforniya\'ya akın etti; eyalet 1850\'de ABD\'ye katıldı ve San Francisco hızla büyüdü.'),
  ('Köleleştirilmiş insanların özgür eyaletlere ve Kanada\'ya kaçmasını sağlayan gizli yardım ağının ve rotaların genel adı nedir?', 'Yeraltı Demiryolu', ['Mayıs Yolu', 'Gizli Geçit Kuzey', 'Santa Fe ve Oregon Yolu ticaret kervanları'], 'Harriet Tubman gibi isimlerin görev yaptığı bu örgüt, Kaçak Köle Yasası\'na rağmen binlerce kişinin kaçmasına yardımcı oldu.'),
  ('1860\'ta Abraham Lincoln\'ün seçilmesinin ardından ilk ayrılan eyalet hangisidir?', 'Güney Carolina', ['Virginia', 'Texas', 'Georgia'], 'Lincoln\'ün seçilmesini köleliğin tehdidi sayan Güney Carolina Aralık 1860\'ta ayrıldı; kısa sürede on bir eyalet Konfederasyon\'u kurdu.'),
  ('Nisan 1861\'de İç Savaş\'ın başlangıcı sayılan ilk çatışma hangi yerde yaşanmıştır?', 'Fort Sumter', ['Gettysburg', 'Bull Run Nehri', 'Antietam Deresi'], 'Güney Carolina\'daki Konfederasyon topçusu, federal elde kalan Fort Sumter\'i bombalayınca savaş fiilen başladı.'),
  ('Temmuz 1863\'te Pennsylvania\'da yaşanan ve Konfederasyon\'un Kuzey\'e yönelik büyük saldırısını durduran muharebe hangisidir?', 'Gettysburg', ['Antietam', 'Fredericksburg', 'Shiloh'], 'General Lee\'nin Kuzey Virginia Ordusu burada ağır kayıp verdi; Gettysburg savaşın dönüm noktalarından sayılır.'),
  ('Nisan 1865\'te Appomattox Court House\'ta General Lee\'nin kime teslim olması savaşı fiilen sona erdirmiştir?', 'General Ulysses Grant\'e', ['General William T. Sherman\'a', 'Başkan Lincoln\'e', 'General McClellan\'a'], 'Konfederasyon\'un ana ordusunun teslimi savaşın sonunu getirdi; birkaç gün sonra Lincoln, Ford Tiyatrosu\'nda vurularak öldürüldü.'),
  ('Yeniden Yapılanma döneminde eski kölelere ekonomik ve eğitim desteği sağlamak için kurulan federal kurumun adı nedir?', 'Freedmen\'s Bureau', ['Pinkerton Teşkilatı', 'Konfederasyon Kongresi', 'Ulusal Banka'], 'Kurum, okul açtı, yiyecek dağıttı ve ücretli çalışma sözleşmelerine aracılık etti; ancak yetersiz kaynak ve Güney direnci engel oldu.'),
  ('Yeniden Yapılanma sonrası Güney\'de eski kölelerin toprak sahibi olamayarak toprak sahiplerine ürünün bir bölümü karşılığı çalıştığı sisteme ne ad verilir?', 'Ortakçılık', ['Hacienda', 'Encomienda', 'Mülk sahipliğine dayalı küçük çiftçilik düzeni'], 'Borç içindeki siyah çiftçiler, ürünün büyük bölümünü toprak sahibine vererek ekonomik bağımlılık içinde kaldı.'),
  ('1896 Plessy v. Ferguson kararı hangi ilkeyi hukuka yerleştirmiştir?', '\'Ayrı ama eşit\' ilkesini', ['Irk ayrımının yasadışı olduğunu', 'Eşit oy hakkını', 'Siyahların askerlik hakkını'], 'Yüksek Mahkeme, demiryolunda ırkların ayrı vagonlarda taşınmasını anayasaya uygun buldu; karar Jim Crow yasalarına hukuki kılıf oluşturdu.'),
  ('Promontory Point\'te 1869\'da bir araya gelen iki demiryolu hattının tamamlanmasıyla ortaya çıkan sonuç nedir?', 'Atlantik ile Pasifik kıyılarını bağlayan kıtalararası demiryolunun açılması', ['Kuzey ile Güney\'in birleşmesi', 'Panama Kanalı\'nın açılması', 'Alaska ile bağlantı'], 'Hattın yapımında Çinli ve İrlandalı göçmenler yoğun çalıştı; ulaşım süresi aylardan günlere düştü.'),
  ('1848\'de New York\'taki Seneca Falls Konvansiyonu\'nda kabul edilen \'Duygular Bildirgesi\' hangi talebi dile getirmiştir?', 'Kadınlara eşit hak ve oy hakkı', ['Köleliğin kaldırılması', 'İçki yasağı ve ahlak kuralları', 'İşçi sendikalarının tanınması'], 'Bildirge, Bağımsızlık Bildirgesi\'nin diliyle \'tüm erkekler ve kadınlar eşit yaratılmıştır\' diyerek kadın hareketini başlattı.'),
  ('1898 Paris Antlaşması ile ABD hangi toprakları İspanya\'dan almıştır?', 'Porto Riko, Guam ve Filipinler', ['Meksika, Kaliforniya ve New Mexico', 'Panama ve Kosta Rika', 'Florida ve Louisiana'], 'İspanya ayrıca Küba\'dan vazgeçti; ABD, 20 milyon dolar ödemesiyle Filipinler\'i satın alırken denizaşırı sömürge devletlerinden biri hâline geldi.'),
  ('1899\'da ABD\'nin \'Açık Kapı Notası\' ile hangi bölgede eşit ticaret koşulları savunulmuştur?', 'Çin', ['Hindistan', 'Panama', 'Hawaii'], 'ABD, Avrupa devletlerinin Çin\'i nüfuz bölgelerine ayırmasına karşı tüm ülkelere eşit ticaret hakkı verilmesini istedi.'),
  ('Latin Amerika\'da ABD\'nin 20. yüzyıl başında Nikaragua, Haiti ve Dominik Cumhuriyeti gibi ülkelere sık sık asker göndermesi hangi dönemle anılır?', 'Muz Savaşları', ['Soğuk Savaş', 'Altın Hummaları', 'Kıta Kongreleri'], 'ABD\'li şirketlerin çıkarlarını ve kanal güvenliğini korumak için yapılan askerî müdahalelere Muz Savaşları denir.'),
  ('José de San Martín\'in 1817\'de And Dağları\'nı aşarak yaptığı sefer hangi ülkenin kurtuluşunda önemli rol oynamıştır?', 'Şili', ['Küba', 'Paraguay', 'Meksika'], 'Arjantin\'den yola çıkan ordu, dağları aşıp Şili\'de İspanyolları yendi; ardından deniz yoluyla Peru\'ya yöneldi.'),
  ('Şili\'nin bağımsızlığında San Martín ile birlikte rol alan ve ülkenin ilk \'Yüce Önderi\' olan kişi kimdir?', 'Bernardo O\'Higgins', ['Antonio José de Sucre', 'Francisco Miranda', 'Agustín de Iturbide'], 'O\'Higgins, 1818\'de Şili bağımsızlığını ilan etti; daha sonra ülkenin yönetimi ona yönelik muhalefet nedeniyle bıraktı.'),
  ('Bolivya devletinin adı kimden alınmıştır?', 'Simón Bolívar', ['Bernardo O\'Higgins', 'José de San Martín', 'Antonio José de Sucre'], 'Bolivya adı kurtarıcı Bolívar\'ın onuruna seçildi; anayasayı da onun isteği üzerine Sucre hazırladı.'),
  ('Toussaint Louverture\'un önderlik ettiği Haiti Devrimi\'nin ardından 1804\'te bağımsızlık ilan eden lider kimdir?', 'Jean-Jacques Dessalines', ['Napolyon Bonapart', 'Simón Bolívar', 'Charles Victor Emmanuel Leclerc'], 'Toussaint Fransızlarca yakalanıp ölünce Dessalines, Fransız ordusunu yendi ve Haiti\'yi bağımsız ilan etti.'),
  ('1862\'de Fransa\'nın Meksika\'ya müdahale etmesinin ardından 1864\'te imparator ilan edilen kişi kimdir?', 'Avusturyalı Arşidük Maximilian', ['Napolyon Bonapart', 'Porfirio Díaz', 'Antonio López de Santa Anna Pérez'], 'Fransız III. Napolyon, Meksika\'nın borç ödemesini bahane edip Maximilian\'ı imparator yaptı; 1867\'de Juárez güçleri onu esir alıp kurşuna dizdi.'),
  ('5 Mayıs 1862\'de Puebla\'da Meksika ordusunun Fransız ordusunu yenmesi hangi ulusal bayramın kökenidir?', 'Cinco de Mayo', ['Día de los Muertos', 'Bağımsızlık Günü', 'Noche de las Velas'], 'Zafer Meksika\'nın Fransa\'ya karşı direniş simgesi oldu; savaş sonunda Fransızlar yine de Mexico City\'ye girdi.'),
  ('MÖ 8. yüzyılda Mısır\'ı fethedip 25. Hanedan\'ı kuran Kuş hükümdarı Piye (Piankhi) hangi merkezden yönetiyordu?', 'Napata', ['Teb', 'Memphis', 'İskenderiye'], 'Piye, Güney Nil\'deki Napata\'dan Mısır\'a yürüdü; Kuşlu firavunlar yaklaşık bir yüzyıl boyunca Mısır\'ı yönetti, ardından Asur saldırılarıyla geri çekildi.'),
  ('Meroe krallığında hükümdar olarak yönetime katılan kadınlara verilen unvan hangisidir?', 'Kandake', ['Tlatoani', 'Sapa İnka', 'Mansa'], 'Kandake (Candace), Meroe\'de kraliçe veya kraliçe anne için kullanılan unvandır; Roma kaynakları da Kandake\'lerin Roma ordusuna karşı direndiğini yazar.'),
  ('Etiyopya\'nın Lalibela kentinde 12.-13. yüzyılda kayaya oyularak yapılan kiliseler hangi hanedan dönemine bağlanır?', 'Zagwe hanedanı', ['Süleymani hanedanı', 'Aksum hanedanı', 'Gondar hanedanı'], 'Kral Lalibela\'nın adıyla anılan 11 monolitik kilise, Etiyopya Hristiyanlığının kutsal bir merkeziydi; \'ikinci Kudüs\' olarak görülürdü.'),
  ('Etiyopya hanedanlığının 1270\'te Yekuno Amlak ile başlayan ve Şeba Kraliçesi ile Süleyman soyundan geldiğini öne süren hanedanı hangisidir?', 'Süleymani hanedanı', ['Zagwe hanedanı', 'Gonderli hanedanı', 'Aksum Krallığı\'nın ilk hanedanı'], 'Hanedan, Kebra Nagast adlı eserdeki anlatıya dayanarak soylarını Kral Süleyman\'a bağlar; 1974\'e kadar Etiyopya\'yı yönetti.'),
  ('Menelik II\'nin 1886-1887\'de kurduğu ve Etiyopya\'nın başkenti olan kent hangisidir?', 'Addis Ababa', ['Aksum', 'Harar', 'Gondar'], 'Menelik, güneyi birleştirip merkezî devleti güçlendirirken Entoto yakınında yeni başkent olarak Addis Ababa\'yı seçti.'),
  ('Haile Selassie\'nin 1974\'te devrilmesinde başı çeken askerî grup hangi adla bilinir?', 'Derg', ['Mau Mau', 'Muhafızlar', 'Interahamwe'], 'Kıtlık, enflasyon ve siyasi hoşnutsuzluk nedeniyle subayların kurduğu Derg imparatoru devirdi; Etiyopya\'da sosyalist yönetim başladı.'),
  ('Batı Afrika\'daki Gana İmparatorluğu\'nun başkenti olarak bilinen ve Sahra kervan yollarının ucunda yer alan kent hangisidir?', 'Kumbi Saleh', ['Timbuktu şehri, Mali döneminde kurulan kervan merkezi', 'Gao, Nijer Nehri kıyısındaki Songhay başkenti', 'Cenne kentindeki Büyük Cami çevresindeki yerleşim'], 'Gana (Wagadu) altın ve tuz ticaretini vergilendirerek zenginleşti; başkent Kumbi Saleh\'in kalıntıları bugünkü Moritanya\'dadır.'),
  ('Mali İmparatorluğu\'nun kurucusu sayılan ve 1235\'teki Kirina Savaşı\'nda Sosso kralı Sumanguru\'yu yenen hükümdar kimdir?', 'Sundiata Keita', ['Askia Muhammed Ture, Songhay\'ın hac yapan hükümdarı', 'Sonni Ali, Songhay\'ın kurucu fatihi', 'Osei Tutu, Asante\'nin birleştiricisi olan hükümdar'], 'Sundiata, Mandinka halkını birleştirerek Mali devletini kurdu; destanı griot adı verilen ozanlar tarafından yüzyıllarca aktarıldı.'),
  ('Batı Afrika\'nın Sahra ötesi ticaretinde deve kervanlarının kullanılmaya başlanması aşağıdakilerden hangisini kolaylaştırmıştır?', 'Çölün aşılmasını ve altın ile tuzun uzun mesafe taşınmasını', ['Atlantik kıyısındaki deniz ticaretinin yoğunlaşıp kervanların terk edilmesini', 'Nehir taşımacılığının bitmesini', 'Demiryolu yapımını'], 'Develer az suyla uzun yol gidebildiği için Sahra kuzey ve güney arasında iletişim ve ticaret kurulmasını mümkün kıldı.'),
  ('1804\'te Usman dan Fodio\'nun Hausa şehir devletlerine karşı başlattığı cihadın sonucunda bugünkü Kuzey Nijerya\'da hangi devlet kurulmuştur?', 'Sokoto Halifeliği', ['Asante Krallığı', 'Mali İmparatorluğu', 'Dahomey Krallığı'], 'Fulani bir alim olan Usman dan Fodio, geleneksel Hausa yönetimlerini dinî yozlaşmış sayarak yıkıp Sokoto merkezli büyük bir halifelik kurdu.'),
  ('Mali\'deki Djenné Büyük Camii\'nin yapımında kullanılan ve her yıl bakımla yenilenen malzeme nedir?', 'Kerpiç', ['Mermer', 'Kesme granit blokları ve kireç harcı', 'Ahşap kütükler'], 'Sahel mimarisinin simgesi olan yapı, yağmur mevsiminden sonra halkın katıldığı toplu sıva töreniyle onarılır.'),
  ('17. yüzyılda Ndongo ve Matamba\'da Portekizlilere karşı uzun süre direnen kraliçe kimdir?', 'Nzinga', ['Kandake Amanirenas', 'Şeba Kraliçesi', 'Kraliçe Ranavalona'], 'Nzinga, Portekiz\'e karşı Hollanda ile ittifak yaptı ve kölelik ticaretinin güçlü olduğu Angola\'da uzun süre bağımsız kalmayı başardı.'),
  ('1896\'da Madagaskar\'ı sömürgesi hâline getiren ve Merina Krallığı\'nı sona erdiren devlet hangisidir?', 'Fransa', ['Portekiz', 'Hollanda', 'İtalya'], 'Fransa, 1895 seferinden sonra adayı ilhak etti ve Kraliçe III. Ranavalona\'yı sürgüne gönderdi.'),
  ('19. yüzyılın başında Zulu yayılmasıyla tetiklenen ve Güney Afrika\'da büyük nüfus hareketleri doğuran sürece ne ad verilir?', 'Mfecane', ['Büyük Trek', 'Mau Mau Ayaklanması', 'Bantu Göçü'], 'Mfecane, \'ezilme ve dağılma\' anlamına gelir; savaşlar sonucu Basotho, Ndebele gibi toplulukların yer değiştirmesine yol açtı.'),
  ('Belçika Kralı II. Leopold\'un 1885\'ten itibaren Kongo havzasını yönettiği yapı hangi adla anılır?', 'Kongo Serbest Devleti', ['Belçika Kongosu devlet idaresi, parlamentonun denetiminde', 'Kongo Konfederasyonu ve ona bağlı Avrupa ticaret şirketleri', 'Orta Afrika Krallığı kuruluşu, yerli hanedanların yönetimiyle'], 'Devlet, Belçika\'ya değil krala ait kişisel bir mülk gibi yönetildi; kauçuk toplama baskısı ve şiddet nedeniyle dünya kamuoyunda büyük tepki doğdu.'),
  ('David Livingstone\'un 1871\'de Tanganyika Gölü kıyısında bulunmasıyla ilişkilendirilen gazeteci kimdir?', 'Henry Morton Stanley', ['Cecil Rhodes', 'Mungo Park', 'Verney Lovett Cameron'], 'New York Herald için çalışan Stanley, kayıp misyoner-kâşifi buldu; Stanley sonradan II. Leopold adına Kongo\'yu da araştırdı.'),
  ('Nil Nehri\'nin kaynağını arayan John Hanning Speke\'in 1858\'de Afrika\'nın en büyük gölü olarak kabul ettiği göl hangisidir?', 'Victoria Gölü', ['Tanganyika Gölü, Büyük Rift Vadisi\'ndeki derin göl', 'Çad Gölü, Sahra\'nın güneyindeki sığ göl', 'Malavi Gölü, Mozambik sınırındaki göl'], 'Speke gölü kraliçeye atfen adlandırdı; Nil\'in kaynağı olduğunu savundu ve bu iddia daha sonra doğrulandı.'),
  ('Cezayir\'de 1832\'den itibaren Fransız işgaline karşı uzun süre direnen lider kimdir?', 'Emir Abdülkadir', ['Sultan Abdülhamid', 'Mehmed Ali Paşa', 'Mansa Musa'], 'Abdülkadir, Fransızlara karşı 1847\'ye kadar direndi; teslim olduktan sonra Şam\'a yerleşti ve Cezayir\'in ulusal sembollerinden biri oldu.'),
  ('Batı Afrika\'da Fransız ilerleyişine karşı 1880\'lerden 1898\'e kadar direnen Mandinka lideri kimdir?', 'Samori Touré', ['Behanzin', 'Usman dan Fodio', 'Moshoeshoe'], 'Samori modern tüfeklerle donattığı ordusuyla Fransızlara uzun süre direndi; 1898\'de yakalanıp sürgüne gönderildi.'),
  ('1905\'te Alman Doğu Afrikası\'nda (Tanganyika) çıkan ve çeşitli etnik grupları birleştiren isyanın adı nedir?', 'Maji Maji İsyanı', ['Mau Mau İsyanı', 'Mahdi (Mehdi) Ayaklanması', 'Herero İsyanı'], 'Pamuk zorunlu tarımına karşı çıkan isyanda \'maji\' (su) adlı kutsal içeceğin kurşunu suya çevireceğine inanıldı; isyan şiddetle bastırıldı.'),
  ('1952-1960 arasında Kenya\'da İngiliz yönetimine ve beyaz yerleşimcilere karşı çıkan, çoğunlukla Kikuyu halkının desteklediği ayaklanma hangisidir?', 'Mau Mau', ['Maji Maji ayaklanması, Alman Doğu Afrika\'sında', 'Boxer ayaklanması, Çin\'deki yabancı karşıtı', 'Mahdi ayaklanması, Sudan\'da Hartum çevresinde'], 'Mau Mau, toprak kaybı ve ayrımcılık yüzünden doğdu; İngilizler olağanüstü hal ilan edip binlerce kişiyi gözaltına aldı, yine de bağımsızlık 1963\'te geldi.'),
  ('Kenya\'nın 1963\'te bağımsızlığını kazandığı dönemde ülkenin ilk başbakanı ve sonra cumhurbaşkanı olan lider kimdir?', 'Jomo Kenyatta', ['Kwame Nkrumah, Gana\'nın kurucu lideri', 'Julius Nyerere, Tanganyika\'nın öğretmen lideri', 'Kenneth Kaunda, Zambiya\'nın bağımsızlık önderi'], 'Kenyatta, Kenya Afrika Ulusal Birliği\'ni yönetip bağımsızlık sonrası uzun yıllar ülkeyi idare etti.'),
  ('1960\'ta Kongo\'nun bağımsızlığının hemen ardından Katanga eyaletinin ayrılıkçı hareketine önderlik eden kişi kimdir?', 'Moïse Tshombe', ['Patrice Lumumba, yeni başbakan', 'Joseph Kasa-Vubu, cumhurbaşkanı', 'Jomo Kenyatta, komşu ülkenin lideri'], 'Maden zengini Katanga\'nın ayrılması Kongo Krizi\'ni başlattı; Belçika destekli ayrılıkçılara karşı BM de devreye girdi.'),
  ('1965\'te Kongo\'da ordu komutanı olarak iktidarı ele geçiren ve 1971\'de ülkenin adını Zaire yapan lider kimdir?', 'Mobutu Sese Seko', ['Laurent Kabila, muhalif lider', 'Moïse Tshombe, eski ayrılıkçı', 'Joseph Kasa-Vubu, ilk cumhurbaşkanı'], 'Mobutu, Soğuk Savaş\'ta Batı desteğiyle otuz yılı aşkın bir süre ülkeyi tek adam rejimiyle yönetti.'),
  ('1967-1970 Nijerya İç Savaşı\'nda (Biafra Savaşı) kendi bağımsızlığını ilan eden bölge hangi halkın yoğun yaşadığı yerdir?', 'Igbo halkının', ['Hausa halkının', 'Yoruba halkının', 'Zulu halkının'], 'Doğu Bölgesi Biafra adıyla ayrılmak istedi; ablukayla yaşanan kıtlıkta çok sayıda sivil öldü, ayrılık bastırıldı.'),
  ('Amílcar Cabral\'ın Gine-Bissau ve Yeşil Burun Adaları\'ndaki hareketi hangi sömürgeci devlete karşı mücadele vermiştir?', 'Portekiz', ['Fransa', 'İngiltere', 'Belçika'], 'Cabral\'ın PAIGC örgütü gerilla savaşıyla bağımsızlık için savaştı; kendisi 1973\'te öldürüldü, ülke aynı yıl bağımsızlığını ilan etti.'),
  ('Namibya\'nın 1990\'da bağımsız olmasına yol açan mücadelede öne çıkan örgüt hangisidir?', 'SWAPO', ['ANC', 'Mau Mau', 'FRELIMO'], 'Güney Batı Afrika Halk Örgütü, Güney Afrika\'nın işgaline karşı uzun yıllar savaştı; BM planıyla yapılan seçimlerin ardından bağımsızlık geldi.'),
  ('Güney Afrika\'da 1948 seçimlerini kazanan Ulusal Parti\'nin yasalaştırdığı ırk ayrımcılığı sisteminin Afrikaanca adı nedir?', 'Apartheid (\'ayrı gelişme\')', ['Ubuntu (\'insanlık ve dayanışma ruhu\')', 'Ujamaa (\'ailecilik\')', 'Négritude (\'siyahlık\')'], 'Apartheid, nüfusu ırk temelinde ayıran ve siyah çoğunluğu siyasi ve ekonomik haklardan yoksun bırakan yasalar bütünüydü.'),
  ('Apartheid rejiminde siyah Güney Afrikalıların kentlerde dolaşmasını denetlemek için taşımak zorunda oldukları belgeye ne ad verilirdi?', 'Geçiş belgesi', ['Vatandaşlık kartı, oy kullanmak için', 'Okul karnesi, eğitime giriş için', 'Askerlik belgesi, ordu çağrısı için'], 'Geçiş yasaları siyahların belirlenen bölgelerde yaşamasını ve çalışmasını zorunlu kıldı; belgesiz yakalananlar cezalandırıldı.'),
  ('1963-1964 Rivonia Davası\'nın Nelson Mandela için sonucu nedir?', 'Ömür boyu hapis cezası alması', ['İdama mahkûm edilmesi', 'Beraat etmesi', 'Sürgüne gönderilmesi'], 'Mandela \'Hazırım\' diyen savunmasıyla dünya gündemine geldi; Robben Adası\'nda 18 yıl da dahil toplam 27 yıl tutuklu kaldı.'),
  ('Apartheid yönetimine karşı uluslararası alanda uygulanan yaptırımlar arasında aşağıdakilerden hangisi yer almıştır?', 'Silah ambargosu ve boykotlar', ['Askerî işgal', 'Güney Afrika\'ya ücretsiz yardım', 'Güney Afrika\'nın NATO\'ya alınması'], '1977\'de BM zorunlu silah ambargosu getirdi; spor müsabakalarından dışlama ve yatırım çekme kampanyaları rejimi yalnızlaştırdı.'),
  ('Güney Afrika\'da Nisan 1994\'te yapılan ilk çok ırklı seçimin sonucu nedir?', 'ANC\'nin kazanması', ['Ulusal Parti\'nin kazanması', 'Seçimlerin iptal edilmesi', 'İnkatha\'nın ülkeyi bölmesi'], 'Yetişkin tüm vatandaşların oy kullandığı ilk seçimde ANC büyük çoğunluk kazandı; Mandela 10 Mayıs 1994\'te göreve başladı.'),
  ('Güney Afrika\'da 1995\'te kurulan Hakikat ve Uzlaşma Komisyonu hangi esasa dayanarak çalışmıştır?', 'İtirafa karşılık af tanıyarak', ['Tüm sorumluları yargılayıp idam ederek', 'Suçlulara tazminat ödeterek', 'Mahkemeleri kapatarak'], 'Komisyon, Başpiskopos Desmond Tutu başkanlığında mağdurların ve failin tanıklıklarını dinledi; amaç intikam yerine uzlaşmaydı.'),
  ('1984 Nobel Barış Ödülü\'nü alan ve Hakikat ve Uzlaşma Komisyonu\'na başkanlık eden din adamı kimdir?', 'Desmond Tutu', ['Steve Biko', 'Albert Luthuli', 'Oliver Tambo'], 'Başpiskopos Tutu, apartheid\'e şiddetsiz muhalefetiyle tanınır; Luthuli 1960\'ta, Mandela ise 1993\'te Nobel almıştır.'),
  ('1910\'da Meksika Devrimi\'ni başlatan ve Porfirio Díaz\'a karşı \'Etkili oy, yeniden seçilme yok\' çağrısı yapan lider kimdir?', 'Francisco Madero', ['Emiliano Zapata, güneydeki köylü ordusunun lideri ve toprak reformu savunucusu', 'Venustiano Carranza, kuzeyli hacienda sahibi ve 1917 Anayasası\'nın mimarı', 'Victoriano Huerta, Madero\'yu deviren ve diktatörlük kuran general'], 'Madero, San Luis Plan\'ıyla ayaklanma çağrısı yaptı ve 1911\'de Díaz\'ı çekilmeye zorladı; ancak 1913\'te Huerta darbesinde öldürüldü.'),
  ('1913\'te Madero\'yu deviren ve kısa süren bir diktatörlük kuran general kimdir?', 'Victoriano Huerta', ['Pancho Villa, kuzeyli süvari komutanı ve eski haydut', 'Álvaro Obregón, Sonora\'dan gelen çiftçi general', 'Plutarco Elías Calles, sonradan cumhurbaşkanı olan subay'], 'Huerta, ABD Büyükelçisi\'nin de rolü olduğu bir darbeyle iktidarı aldı; Villa, Zapata ve Carranza\'nın birleşik muhalefetiyle 1914\'te devrildi.'),
  ('Arjantin\'de 1940\'lı yıllarda Juan Perón\'un işçi sınıfına dayanarak oluşturduğu siyasi harekete ne ad verilir?', 'Peronizm', ['Caudillismo, yerel güçlü adamlara dayalı yönetim', 'Liberalizm, serbest piyasa ve dış ticareti savunan çizgi', 'Bolivarizm, kıta birliğini hedefleyen akım'], 'Perón, sendikalara ve ücret artışlarına dayanan popülist bir yönetim kurdu; eşi Eva Perón da kadın oy hakkı ve yardım kuruluşlarıyla sevildi.'),
  ('Kolombiya\'da 1948\'de liberal lider Jorge Eliécer Gaitán\'ın öldürülmesiyle başlayan ve aylarca süren şiddet olaylarına ne ad verilir?', 'Bogotazo', ['Cinco de Mayo, Puebla zaferini anan bayram', 'Noche Triste, İspanyolların Tenochtitlan\'dan kaçışı', 'Jacobo dönemi, kıta ölçekli çatışmalar'], 'Gaitán\'ın ölümü Bogota\'da ayaklanmaya, sonra \'La Violencia\' denen uzun iç çatışmaya yol açtı.'),
  ('Nikaragua\'da 1927-1933 arasında ABD işgaline karşı gerilla savaşı yürüten lider kimdir?', 'Augusto César Sandino', ['Anastasio Somoza, sonraki diktatör', 'Emiliano Zapata, Meksika devrimcisi', 'Francisco Madero, Meksika devrimcisi'], 'Sandino, işgalci Amerikan deniz piyadelerine karşı savaştı; ABD çekilince Somoza\'nın Ulusal Muhafız Birliği tarafından öldürüldü.'),
  ('Amerika kıtasında kullanılan \'Latin Amerika\' adı hangi bölgeleri anlatır?', 'Latince kökenli dillerin konuşulduğu Amerika', ['Latince konuşulan Amerika', 'Yalnızca Güney Amerika\'nın İspanyolca konuşulan ülkeleri', 'Katolik Kilisesi\'nin merkezi olan Amerika\'nın bölgeleri'], 'Terim 19. yüzyılda Fransa tarafından yaygınlaştırıldı; Meksika\'dan Arjantin\'e kadar uzanan geniş coğrafyayı kapsar.'),
  ('Murabıtlardan sonra Kuzey Afrika ve Endülüs\'e egemen olan, kurucusu İbn Tümert\'in fikirlerine dayanan hanedan hangisidir?', 'Muvahhidler', ['Hafsiler, Tunus merkezli', 'Saadiler, 16. yüzyıl Fas hanedanı', 'Memlükler, Kahire merkezli'], 'Muvahhidler (Almohad) tevhid vurgusuyla Atlas Dağları\'ndan çıktı; Marakeş\'i başkent yapıp Sevilla\'da Giralda gibi yapılar bıraktı.'),
  ('1921\'de İspanyol ordusunu Annual Savaşı\'nda ağır yenilgiye uğratan Rif direnişinin lideri kimdir?', 'Abdülkerim el-Hattabi', ['Ömer Muhtar, Libya\'nın direniş lideri', 'Emir Abdülkadir, Cezayir\'in direniş lideri', 'Habib Burgiba, Tunus\'un bağımsızlık lideri'], 'Hattabi, Rif Dağları\'nda Rif Cumhuriyeti\'ni ilan etti; İspanya-Fransa ortak harekâtıyla 1926\'da teslim oldu.'),
  ('İtalya\'ya karşı Libya\'da yirmi yıl boyunca direnen ve 1931\'de asılan \'Çölün Aslanı\' lakaplı komutan kimdir?', 'Ömer Muhtar', ['Abdülkerim el-Hattabi', 'Mehdi Muhammed Ahmed', 'Cemal Abdülnasır'], 'Senusi tarikatından gelen Muhtar, gerilla yöntemiyle İtalyan işgaline direndi; yakalanıp idam edildi ve Libya direnişinin sembolü oldu.'),
  ('1655\'te İngiltere\'nin İspanya\'dan alarak büyük şeker üretim merkezine dönüştürdüğü Karayip adası hangisidir?', 'Jamaika', ['Küba, İspanya\'nın uzun süre elinde tuttuğu ada', 'Barbados, İngiltere\'nin ilk sömürgesi olan ada', 'Hispaniola, Kolomb\'un ikinci yerleşim yeri'], 'Port Royal gibi limanlarıyla ünlü Jamaika, 17. yüzyılda İngiliz korsanlarının ve şeker plantasyonlarının merkezi oldu.'),
  ('Jamaika\'da kaçak kölelerin dağlık bölgelerde kurduğu ve İngilizlerle 1739\'da antlaşma yapan topluluklara ne ad verilir?', 'Maroonlar', ['Quilombolar, Brezilya\'daki kaçak topluluklar', 'Bantular, Orta Afrika\'daki dil topluluğu', 'Criollolar, Amerika\'da doğan beyazlar'], 'Maroon toplulukları uzun savaşlardan sonra İngilizlerden özerklik aldı; bu, kölelik karşıtı direnişin bilinen örneklerindendir.'),
  ('Karayipler\'de 17.-18. yüzyıl korsanlığında Edward Teach (Karasakal) hangi dönemle ilgili bir figürdür?', 'Korsanlığın \'Altın Çağı\'', ['Haçlı Seferleri', 'Napolyon Savaşları\'nın deniz seferleri dönemi', 'Soğuk Savaş'], 'Teach 1718\'de Kuzey Karolina açıklarında öldürüldü; korsan tehdidi Royal Navy\'nin ticareti korumasıyla azaldı.'),
  ('Haiti Devrimi\'nin başlangıcı sayılan 1791 ayaklanması hangi sömürgede çıkmıştır?', 'Saint-Domingue', ['Barbados, İngiliz şeker adası', 'Cuba, İspanyol sömürgesi', 'Curaçao, Hollanda adası'], 'Saint-Domingue, dünya şeker üretiminin büyük kısmını sağlayan Fransız sömürgesiydi; köleler burada uzun mücadele sonunda bağımsız devlet kurdu.'),
  ('1844\'te Haiti\'den ayrılarak bağımsızlığını ilan eden Karayip devleti hangisidir?', 'Dominik Cumhuriyeti', ['Küba', 'Jamaika', 'Porto Riko'], 'Adanın doğusundaki İspanyol kökenli nüfus, Haiti yönetimine tepki göstererek ayrıldı; bağımsızlık daha sonra İspanya ve ABD müdahaleleriyle kesintiye uğradı.'),
  ('1492\'de Kolomb\'un Amerika\'ya ilk ayak bastığı adanın yerli halkın Guanahani dediği adada olduğu düşünülür. Bu ada hangi takımada içinde yer alır?', 'Bahamalar', ['Küçük Antiller, Doğu Karayipler\'deki zincir', 'Büyük Antiller, Küba ve Hispaniola\'nın yer aldığı grup', 'Kanarya Adaları, Atlantik\'teki İspanyol adaları'], 'Kolomb ilk landfall\'ı Bahamalar\'ın bir adasında yapmış; yerli Lucayan Taínoları onu karşılamıştı.'),
  ('1587\'de Roanoke Adası\'ndaki İngiliz yerleşiminin sakinlerinin 1590\'da yerleşimi terk edilmiş bulunduğu ve geride yalnızca \'Croatoan\' yazısı kaldığı olay neyin simgesi olmuştur?', 'Kayıp Koloni gizemi', ['Mayflower yolculuğunun başarısızlığı', 'Salem cadı davalarının kökeni', 'Jamestown\'un ilk iyi hasadı'], 'Yerleşimcilerin kaderi bugün de kesinlik kazanmamıştır; olası açıklamalar arasında kıtlık, yerli halklarla birleşme ve göç vardır.'),
  ('1565\'te İspanyollar tarafından Florida\'da kurulan ve bugün ABD sınırları içindeki en eski sürekli Avrupa kenti sayılan yerleşim hangisidir?', 'St. Augustine', ['Jamestown, Virginia\'daki İngiliz yerleşimi', 'Plymouth, Pilgrim\'lerin yerleşimi', 'New Orleans, Fransız Louisiana kenti'], 'Pedro Menéndez de Avilés\'in kurduğu St. Augustine, Fransız Huguenot yerleşimine karşı bir savunma noktasıydı.'),
  ('1670\'te İngiltere\'de kurulan ve Kanada\'nın geniş bölgelerinde kürk ticaretini yürüten şirket hangisidir?', 'Hudson\'s Bay Company', ['Virginia Company, Jamestown\'u kuran şirket', 'Massachusetts Bay Company, Puritan şirketi', 'Dutch West India Company, Hollanda şirketi'], 'Şirket, yerli avcılarla kürk takasına dayanan ticaret ağı kurdu; Kanada\'nın batıya doğru keşfinde önemli rol oynadı.'),
  ('Rosa Parks\'ın Aralık 1955\'te Montgomery\'de otobüste yerini beyaz bir yolcuya vermemesi hangi gelişmeye yol açmıştır?', 'Montgomery otobüs boykotuna', ['Başkanın istifasına ve seçimlerin yenilenmesine', 'Anayasanın değişmesine', 'Silahlı ayaklanmaya'], 'Boykot, Martin Luther King\'in lider olarak öne çıkmasını sağladı; Yüksek Mahkeme toplu taşımada ayrımı anayasaya aykırı buldu.'),
  ('1957\'de Arkansas\'ın Little Rock kentinde dokuz siyah öğrencinin liseye girişinde Başkan Eisenhower\'ın aldığı önlem nedir?', 'Federal birlik göndermek', ['Eyalet milisine okulu kapattırıp öğrencileri geri çevirtmek', 'Öğrencileri başka bir okula taşımak', 'Mahkeme kararını askıya almak'], 'Vali okula girişi engelleyince Eisenhower federal askerleri gönderdi; olay federal hükümetin eşitlik uygulamasındaki ilk büyük sınavlarındandır.'),
  ('1963 Washington Yürüyüşü\'nde Martin Luther King\'in \'Bir hayalim var\' konuşmasının temel çağrısı nedir?', 'Irk ayrımının bitip eşitliğin gelmesi', ['Siyahlar için ayrı bir devlet kurulup ayrılınması', 'Vietnam\'dan çekilme', 'Vergilerin kaldırılması'], 'Yüz binlerce kişinin katıldığı yürüyüş, iş ve özgürlük talebiyle sivil haklar yasasına duyulan desteği güçlendirdi.'),
  ('Martin Luther King\'in 1963\'te Birmingham Hapishanesi\'nden yazdığı mektubun savunduğu ilke nedir?', 'Şiddetsiz sivil itaatsizlik', ['Silahlı direniş', 'Beklemeyi ve ılımlı davranmayı sürdürmeyi', 'Siyahların Afrika\'ya dönüşünü'], 'King, adaletsiz yasalara uymamanın ahlaki bir görev olduğunu savunup bekleme çağrılarını eleştirdi.'),
  ('1909\'da kurulan NAACP\'nin (Ulusal Renkliler Gelişim Derneği) başlıca çalışma biçimi nedir?', 'Hukuk davaları ve kampanyalar', ['Silahlı birlikler kurma', 'Siyahları gemilerle Afrika\'ya taşıma', 'Ticari şirket işletme'], 'Örgüt, mahkemelerde ayrımı hedef alan davalar açtı; Brown kararı bu hukuki mücadelenin zirvesidir.'),
  ('1825\'te açılan Erie Kanalı\'nın ABD ekonomisine katkısı nedir?', 'Ticareti ucuzlatması', ['Ülkenin güneyini doğrudan Karayipler\'e bağlaması', 'Nehir yolunu tamamen kapatması', 'Kıyı ticaretini yasaklaması'], 'Kanal, New York\'u Ohio Vadisi\'ne bağladı; taşıma maliyeti düştü, New York ülkenin başlıca ticaret kenti hâline geldi.'),
  ('William Lloyd Garrison\'ın 1831\'de çıkardığı gazete \'The Liberator\'ın hedefi nedir?', 'Köleliğin derhâl kaldırılması', ['Köleliğin yavaş yavaş azaltılması', 'Siyahların topluca Afrika\'ya yerleştirilmesi', 'Kuzey\'in Güney\'den ayrılması'], 'Garrison kölelik karşıtı hareketin radikal kanadını temsil etti; kölelik \'günah\' olduğundan ödünsüz mücadele edilmesini savundu.'),
  ('Panama Kanalı\'nı ilk kez 1880\'lerde yapmaya girişen ve sarı humma ile mali sorunlar yüzünden başarısız olan girişimin lideri kimdir?', 'Ferdinand de Lesseps', ['Theodore Roosevelt', 'William Crawford Gorgas Jr.', 'Cecil Rhodes'], 'Süveyş Kanalı\'nı açan Lesseps, Panama\'da hastalık ve mühendislik zorlukları yüzünden iflasa uğradı; ABD işi sonra devraldı.'),
  ('1900\'lerin başında Panama Kanalı çalışmalarında sivrisinek kontrolüyle sarı humma salgınını durduran hekim kimdir?', 'William Gorgas', ['Louis Pasteur', 'Robert Koch', 'Alexander Fleming'], 'Gorgas, sivrisinek üreme yerlerini ortadan kaldırarak hastalıkla mücadeleyi başarıya ulaştırdı; kanal 1914\'te açıldı.'),
  ('19. yüzyılın sonunda ABD\'de Knights of Labor ve 1886\'da kurulan AFL (Amerikan Emek Federasyonu) neyi temsil eder?', 'Sendikal hak mücadelesini', ['Sermaye ortaklıklarını', 'Çiftçi sendikalarını', 'Misyonerlik ve hayır dernekleri ağını'], 'AFL, vasıflı işçileri örgütleyip ücret ve çalışma saatleri konusunda pazarlık yapan bir sendikalar federasyonuydu.'),
  ('I. Dünya Savaşı sırasında Doğu Afrika\'da Alman komutan Paul von Lettow-Vorbeck\'in uyguladığı yöntem aşağıdakilerden hangisidir?', 'Gerilla savaşı', ['Kıyıda donanma ile Britanya\'yı yenme', 'Büyük topçu mevzileriyle Nairobi kuşatması', 'Tren hattıyla düzenlenen büyük meydan savaşları'], 'Lettow-Vorbeck, sınırlı kuvvetle kıtlık ve hastalığa rağmen savaş sonuna kadar direndi; ancak halk ağır acı çekti.'),
  ('Afrikalı ordulara karşı Avrupa orduları 19. yüzyıl sonunda hangi askerî üstünlükle zafer kazanmıştır?', 'Makineli tüfek üstünlüğü', ['Daha çok sayıda süvari ve deve birliği', 'Daha uzun savaş geleneği', 'Daha çok kale ve sur'], 'Modern geri doldurmalı tüfekler ve makineli tüfekler, geleneksel orduların hücum taktiklerine karşı belirleyici oldu.'),
  ('Peru\'nun yüksek bölgesindeki Chavín de Huántar, Andlar tarihi bakımından neyi simgeler?', 'Erken dinî ve sanatsal etkiyi', ['Pizarro\'nun Peru\'daki ilk karargâhını', 'İnka başkentini', 'Moche krallarının mezarlığını'], 'Yaklaşık MÖ 900-200 arasında gelişen merkez, jaguar ve yılan motifli sanat üslubunu çevre bölgelere yaydı.'),
  ('Amazon havzasında yerlilerin yüzyıllar boyunca ürettiği, verimli koyu renkli toprağa ne ad verilir?', 'Terra preta', ['Chinampa', 'Andenes', 'Guano'], 'Kömür, kemik ve seramik parçalarıyla zenginleştirilen bu toprak, kıtanın yağmur ormanlarında yoğun yerleşimin ve tarımın mümkün olduğunu gösterir.'),
  ('Mapuche halkının 16. yüzyılda İspanyol işgaline karşı Şili\'nin güneyinde uzun süre direnmesinde öne çıkan lider kimdir?', 'Lautaro', ['Atahualpa', 'Tupac Amaru', 'Cuauhtémoc'], 'Mapuche, İnka\'ya da boyun eğmemişti; Arauco Savaşı yüzyıllarca sürdü ve bölge bağımsız kaldı.'),
  ('Kolombiya\'da Muisca halkının Guatavita Gölü\'ndeki altın törenlerinden doğan efsane hangisidir?', 'El Dorado', ['Atlantis', 'Camelot', 'Shangri-La'], 'Hükümdarın üzerine altın tozu serpilip gölde yıkanması anlatısı, İspanyolları Güney Amerika içlerinde altın şehir aramaya sürükledi.'),
  ('Ohio Vadisi\'ndeki höyükleri ve Serpent Mound gibi toprak yapılarıyla bilinen Kuzey Amerika kültürü hangisidir?', 'Adena-Hopewell', ['Cherokee', 'Mohawk', 'Navajo (Diné) toplulukları'], 'Hopewell kültürü (yaklaşık MÖ 200-MS 500) uzak mesafe ticareti ve anıtsal toprak yapılarıyla ünlüdür.'),
  ('Cizvitlerin 17. yüzyılda Paraguay\'da Guaraní halkı için kurduğu \'reducciones\' (misyon köyleri) hangi amaca hizmet etmiştir?', 'Yerlileri köle avından korumak', ['Yerli halkı İspanyol ordusuna asker olarak katmak', 'Altın madeni işletmek', 'Kıyı limanlarını savunmak'], 'Misyonlarda eğitim, tarım ve müzik düzenli bir toplum biçimi kurdu; köle avcılarından korunma da cazibelerinden biriydi.'),
  ('Aşağıdaki olaylardan hangisi kronolojik olarak en erkendir?', 'Tenochtitlan\'ın İspanyollara düşmesi', ['Amerikan Bağımsızlık Bildirgesi\'nin kabulü, Philadelphia\'da bir Kıta Kongresi sonucunda', 'Haiti\'nin bağımsızlığının ilan edilmesi ve bir köle devriminin zaferi', 'Berlin Konferansı\'nda Afrika paylaşımı kurallarının belirlenmesi'], 'Tenochtitlan 1521\'de düştü; Bağımsızlık Bildirgesi 1776, Haiti bağımsızlığı 1804, Berlin Konferansı 1884-1885 tarihlidir.'),
  ('Zulu Kralı Cetshwayo\'nun 1879\'da İngiliz birliğini yendiği muharebe hangisidir?', 'Isandlwana', ['Omdurman', 'Adua', 'Ayacucho'], 'Zulu impi\'leri İngiliz kampını basıp ağır kayıp verdirdi; ancak İngilizler kısa sürede karşı saldırıya geçip krallığı yıktı.'),
  ('1932-1935 Chaco Savaşı hangi iki Güney Amerika ülkesi arasında yaşanmıştır?', 'Bolivya ve Paraguay', ['Şili ve Peru', 'Arjantin ve Brezilya', 'Kolombiya ve Venezuela'], 'Savaş, petrol bulunduğu sanılan Chaco Boreal bölgesi yüzünden çıktı; ağır kayıplarla sonuçlandı ve Paraguay\'ın lehine bitti.'),
  ('Yoruba geleneğinde dünyanın yaratıldığı yer sayılan ve terakota ile bronz baş heykelleriyle bilinen kent hangisidir?', 'Ife', ['Kano', 'Gao', 'Kumasi'], 'Ife, 12.-15. yüzyıllarda sanatsal gelişme gösterdi; gerçekçi baş heykelleri Afrika sanat tarihinin önemli örnekleridir.'),
  ('Büyük Zimbabve kalıntılarında bulunan ve bugün Zimbabve bayrağında yer alan sembol nedir?', 'Zimbabve Kuşu', ['Kartal ve yılan', 'Güneş diski ve haç', 'Mızrak ve kalkan'], 'Duvarlar arasında bulunan yontma kuş heykeller, Shona hükümdarlığının simgesi sayılır ve ülke adını da bu kentten almıştır.'),
  ('Uganda\'daki Buganda Krallığı\'nın hükümdarına verilen unvan nedir?', 'Kabaka', ['Mwami', 'Oba', 'Asantehene'], 'Buganda, 19. yüzyılda Kabaka Mutesa I döneminde Avrupalı gezginlerle temas kurdu ve bölgenin güçlü krallığı olarak ön plana çıktı.'),
  ('1960\'ların başında Mozambik\'te silahlı mücadele başlatan ve 1975\'te bağımsızlığı sağlayan hareket hangisidir?', 'FRELIMO', ['SWAPO', 'MPLA', 'PAIGC'], 'Mozambik Kurtuluş Cephesi, 1964\'te Portekiz sömürge yönetimine karşı silahlı mücadele başlattı; Samora Machel ilk devlet başkanı oldu.'),
  ('1979 Lancaster House Anlaşması\'nın sonucu olarak Rodezya\'da hangi gelişme yaşandı?', 'Çoğunluk yönetimine geçiş', ['Beyaz azınlık yönetiminin kalıcı olması', 'Rodezya\'nın Güney Afrika Birliği\'ne katılması', 'Mozambik ile birleşme'], 'Londra\'daki müzakereler, silahlı mücadele ile beyaz yönetim arasındaki çatışmayı sona erdirdi; seçimlerden sonra Robert Mugabe başbakan oldu.'),
  ('Powhatan Konfederasyonu\'nun lideri Powhatan\'ın kızı Pocahontas\'ın Jamestown tarihindeki önemi nedir?', 'Barışa aracılık etmesi', ['Kolonideki ilk valilik görevi', 'İlk matbaayı Jamestown\'da kurması', 'Tütün ticaretini yasaklaması'], 'Pocahontas\'ın evliliği yıllarca süren gerginliği hafifletti; İngiltere\'ye gidip 1617\'de orada öldü.'),
  ('Mısır\'ın Fatımi döneminden kalan ve bugün de kullanılan örneği olan Ezher\'in İslam dünyasında üstlendiği rol nedir?', 'Önemli bir ilim merkezi olması', ['Askerî akademi olması', 'Sarayın hazinesi olması', 'Kızıldeniz\'de ticaret limanı olması'], 'Ezher yüzyıllar boyunca Sünni dünyanın başlıca öğrenim merkezlerinden biri hâline gelmiştir.'),
  ('Mısır\'da 1956 sonrası Nasır\'ın benimsediği \'Pan-Arabizm\' anlayışının amacı nedir?', 'Arap birliğini sağlamak', ['Mısır\'ı Avrupa\'ya bağlamak', 'Sudan\'ı kendine bağlı sömürge yapmak', 'İsrail ile ittifak kurmak'], 'Nasır, 1958\'de Suriye ile Birleşik Arap Cumhuriyeti\'ni kurdu; ancak birlik 1961\'de dağıldı.'),
  ('Maya mimarisinde kemer yerine kullanılan ve iki yandan taşları kademeli çıkıntı yaparak birleştiren üst örtü sistemine ne ad verilir?', 'Çıkmalı (korbel) kemer', ['Yuvarlak tonoz', 'Gotik sivri kemer', 'Kubbe pandantifi'], 'Mayalar gerçek kemeri kullanmayıp taş sıralarını yavaş yavaş içeri çıkartarak dar mekânlar örttü; bu teknik tapınak odalarında görülür.'),
  ('İnka toplumunda seçilmiş kadınların yaşadığı ve güneş tanrısına hizmet ettikleri kuruma ne ad verilirdi?', 'Acllahuasi', ['Calmecac', 'Telpochcalli', 'Tzompantli'], 'Aclla denen seçilmiş kadınlar kumaş dokur, chicha yapar ve törenlerde hizmet ederdi; bazıları soyluların eşi olurdu.'),
  ('Lewis ve Clark seferine rehberlik eden Shoshone kadını Sacagawea\'nın seferdeki katkısı nedir?', 'Tercümanlık ve barışçıl temas', ['Orduyu yönetmek', 'Haritaları çizip seferin planını yapmak', 'Pasifik\'te gemi kullanmak'], 'Sacagawea yanındaki bebeğiyle seferin barışçıl bir heyet olduğunu göstererek yerli gruplarla ilişkileri kolaylaştırdı.'),
  ('İç Savaş başında Kuzey\'in Güney\'i denizden ablukaya alıp Mississippi\'yi ele geçirerek boğmayı öngören stratejiye ne ad verilir?', 'Anaconda Planı', ['Manifest Destiny', 'Domino Teorisi', 'Çevreleme Planı'], 'General Winfield Scott\'ın önerdiği plan, Güney\'in ekonomisini ve ikmalini sınırlamayı amaçladı; savaşın sonucunu etkileyen deniz ablukası da bunun parçasıdır.'),
  ('1892\'de New York Limanı\'ndaki Ellis Adası\'nın açılması ABD tarihinde neyi simgeler?', 'Göçmenlerin kabul merkezi', ['Kölelerin gemilerden indirilip satıldığı pazarı', 'Askerî tersaneyi', 'Yerlilerin sürüldüğü yeri'], 'Adada yaklaşık 12 milyon kişi işlem gördü; ülkenin \'göçmenler ülkesi\' kimliğinin sembollerinden biridir.'),
  ('Tunus\'un ilk Cumhurbaşkanı Habib Burgiba\'nın 1956 Kişisel Statü Yasası ile getirdiği yenilik nedir?', 'Çok eşliliğin yasaklanması', ['Kadınların oy hakkının kaldırılması', 'Tüm eğitimin dinî okullara devredilmesi', 'Kralın yetkilerinin artırılması'], 'Burgiba, Arap dünyasında dikkat çeken bir aile hukuku reformu yaptı; kadın hakları Tunus\'un bağımsızlık sonrası modernleşmesinin simgesidir.'),
  ('Trans-Sahra ticaretinin Müslüman Berberi, Tuareg ve Arap tüccarları, Batı Afrika\'dan hangi malı Akdeniz dünyasına taşırdı?', 'Altın ve köleler', ['Petrol ve doğal gaz', 'Kahve', 'Şarap'], 'Altın Avrupa\'da para basımının ana kaynaklarındandı; Sahra altı Afrika\'dan getirilen köleler de Kuzey Afrika pazarlarında satılırdı.'),
];
